/**
 * semantic-release configuration.
 *
 * This repository's commits are produced by ADW agents and carry an agent
 * name before the conventional type, e.g. `build-agent: feat: add X` or
 * `plan-orchestrator: chore: expand README`. The stock conventional-commits
 * header pattern does not match that prefix, so every agent commit would
 * parse as `type: null` and never trigger a release. `parserOpts` below
 * extends the standard pattern with an optional `<agent-name>: ` prefix.
 *
 * The prefix is constrained to a hyphenated lowercase token
 * (`[a-z0-9]+(?:-[a-z0-9]+)+`) so it can never swallow a bare conventional
 * type (`feat`, `fix`, `chore`, ... contain no hyphen) — a header like
 * `feat: fix: something` still parses as type `feat`, not agent `feat`.
 * The prefix is a non-capturing group, so `headerCorrespondence` stays
 * identical to the `conventionalcommits` preset's and no downstream plugin
 * needs to know agents exist.
 */
const parserOpts = {
  headerPattern: /^(?:[a-z0-9]+(?:-[a-z0-9]+)+: )?(\w*)(?:\((.*)\))?!?: (.*)$/,
  breakingHeaderPattern: /^(?:[a-z0-9]+(?:-[a-z0-9]+)+: )?(\w*)(?:\((.*)\))?!: (.*)$/,
  headerCorrespondence: ['type', 'scope', 'subject'],
};

const isDryRun = process.env.SEMANTIC_RELEASE_DRY_RUN === 'true';

const plugins = [
  ['@semantic-release/commit-analyzer', { preset: 'conventionalcommits', parserOpts }],
  ['@semantic-release/release-notes-generator', { preset: 'conventionalcommits', parserOpts }],
];

if (!isDryRun) {
  plugins.push(
    ['@semantic-release/npm', {}],
    ['@semantic-release/github', { successComment: false, failComment: false }],
  );
}

export default {
  branches: ['main'],
  tagFormat: 'v${version}',
  plugins,
};

/**
 * Runs semantic-release in dry-run mode against a branch and prints the
 * computed next release version, so a PR that would never publish (or that
 * would recompute the hand-published 1.0.0 baseline) is caught before
 * merge. Dependency-free (Node built-ins only) so it runs on a bare CI
 * runner. Run via `bun run release:dry-run`.
 */
import { spawnSync } from 'node:child_process';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

function fail(message: string): never {
  console.error(`FAIL: ${message}`);
  process.exit(1);
}

function resolveBranch(): string {
  const envBranch = process.env.DRY_RUN_BRANCH;
  if (envBranch && envBranch.trim()) return envBranch.trim();

  const result = spawnSync('git', ['rev-parse', '--abbrev-ref', 'HEAD'], {
    cwd: REPO_ROOT,
    encoding: 'utf-8',
  });
  if (result.status !== 0 || !result.stdout.trim()) {
    fail(`could not resolve current branch: ${result.stderr}`);
  }
  return result.stdout.trim();
}

function main(): void {
  const branch = resolveBranch();
  console.log(`==> semantic-release --dry-run against branch "${branch}"`);

  const semanticReleaseBin = path.join(REPO_ROOT, 'node_modules', 'semantic-release', 'bin', 'semantic-release.js');
  const result = spawnSync(
    'node',
    [semanticReleaseBin, '--dry-run', '--no-ci', '--branches', branch],
    {
      cwd: REPO_ROOT,
      encoding: 'utf-8',
      env: {
        ...process.env,
        SEMANTIC_RELEASE_DRY_RUN: 'true',
        // On GitHub Actions `pull_request` events GITHUB_REF is `refs/pull/<n>/merge`,
        // and env-ci hands that to semantic-release as the current branch. `--no-ci`
        // only skips the pull-request early return, not branch detection, so the run
        // would end with "configured to only publish from <branch>" and exit 0 without
        // analyzing anything. Steer env-ci at the branch actually being dry-run instead.
        // Outside GitHub Actions env-ci ignores both variables and asks git.
        GITHUB_EVENT_NAME: 'push',
        GITHUB_REF: `refs/heads/${branch}`,
      },
    },
  );

  const combinedOutput = `${result.stdout ?? ''}${result.stderr ?? ''}`;
  process.stdout.write(result.stdout ?? '');
  process.stderr.write(result.stderr ?? '');

  if (result.status !== 0) {
    fail(`semantic-release --dry-run exited with status ${result.status}`);
  }

  const versionMatch = combinedOutput.match(/the next release version is (\d+\.\d+\.\d+)/i);
  if (!versionMatch) {
    console.log('==> no release would be triggered by this branch');
    process.exit(0);
  }

  const nextVersion = versionMatch[1];
  if (nextVersion === '1.0.0') {
    fail('computed next release version is 1.0.0 — the v1.0.0 baseline must never be recomputed. Verify the v1.0.0 tag is reachable.');
  }

  console.log(`==> next release version: ${nextVersion}`);
}

main();

/**
 * Asserts the agent-prefix-aware commit header pattern in `release.config.js`
 * matches both ADW agent-prefixed commits (`build-agent: feat: …`) and plain
 * conventional commits (`feat: …`), and that the pattern actually drives the
 * real `@semantic-release/commit-analyzer` to the release types the issue
 * specifies. Imports the shipped `parserOpts` object directly — never a copy
 * — so a change to `release.config.js` cannot silently diverge from what
 * these tests assert.
 */
import { describe, expect, it } from 'vitest';
import { analyzeCommits } from '@semantic-release/commit-analyzer';
import releaseConfig from '../../release.config.js';

interface AnalyzerPluginConfig {
  preset: string;
  parserOpts: {
    headerPattern: RegExp;
    breakingHeaderPattern: RegExp;
    headerCorrespondence: string[];
  };
}

const [, analyzerEntry] = releaseConfig.plugins[0] as [string, AnalyzerPluginConfig];
const { parserOpts } = analyzerEntry;

const noopLogger = { log() {}, error() {} };

interface CommitFixture {
  header: string;
  body?: string;
}

function toCommit({ header, body }: CommitFixture): { hash: string; message: string } {
  return { hash: '0'.repeat(40), message: body ? `${header}\n\n${body}` : header };
}

async function analyze(fixtures: CommitFixture[]): Promise<string | null> {
  return analyzeCommits(
    { preset: 'conventionalcommits', parserOpts },
    { commits: fixtures.map(toCommit), logger: noopLogger, cwd: process.cwd(), env: {}, options: {} },
  );
}

describe('release.config.js — headerPattern', () => {
  it.each([
    ['build-agent: feat: add forgeProviders assembly', 'feat'],
    ['review-patch-agent: fix: correct token resolution', 'fix'],
    ['plan-orchestrator: chore: expand README', 'chore'],
    ['document-agent: docs: document package build', 'docs'],
    ['feat: add worktree probe', 'feat'],
    ['fix: handle ENOENT', 'fix'],
    ['chore: bump deps', 'chore'],
    ['feat: fix: colon in the subject', 'feat'],
  ])('%s -> type %s', (header, expectedType) => {
    const match = header.match(parserOpts.headerPattern);
    expect(match, `expected "${header}" to match headerPattern`).not.toBeNull();
    expect(match?.[1]).toBe(expectedType);
  });

  it('captures an agent-prefixed scoped subject', () => {
    const match = 'build-agent: feat(git): scoped subject'.match(parserOpts.headerPattern);
    expect(match).not.toBeNull();
    expect(match?.[1]).toBe('feat');
    expect(match?.[2]).toBe('git');
    expect(match?.[3]).toBe('scoped subject');
  });

  it('does not match a merge commit header', () => {
    expect('Merge pull request #6 from paysdoc/branch'.match(parserOpts.headerPattern)).toBeNull();
  });
});

describe('release.config.js — breakingHeaderPattern', () => {
  it('matches an agent-prefixed breaking header', () => {
    expect('build-agent: feat!: drop legacy layer'.match(parserOpts.breakingHeaderPattern)).not.toBeNull();
  });

  it('matches a plain scoped breaking header', () => {
    expect('feat(git)!: rename export'.match(parserOpts.breakingHeaderPattern)).not.toBeNull();
  });

  it('does not match a non-breaking agent-prefixed header', () => {
    expect('build-agent: feat: normal'.match(parserOpts.breakingHeaderPattern)).toBeNull();
  });
});

describe('release.config.js — analyzeCommits release types', () => {
  it('build-agent: feat: … -> minor', async () => {
    expect(await analyze([{ header: 'build-agent: feat: add forgeProviders assembly' }])).toBe('minor');
  });

  it('review-patch-agent: fix: … -> patch', async () => {
    expect(await analyze([{ header: 'review-patch-agent: fix: correct token resolution' }])).toBe('patch');
  });

  it('plan-orchestrator: chore: … -> null', async () => {
    expect(await analyze([{ header: 'plan-orchestrator: chore: expand README' }])).toBeNull();
  });

  it('document-agent: docs: … -> null', async () => {
    expect(await analyze([{ header: 'document-agent: docs: document package build' }])).toBeNull();
  });

  it('plain feat: … -> minor', async () => {
    expect(await analyze([{ header: 'feat: add worktree probe' }])).toBe('minor');
  });

  it('plain fix: … -> patch', async () => {
    expect(await analyze([{ header: 'fix: handle ENOENT' }])).toBe('patch');
  });

  it('plain chore: … -> null', async () => {
    expect(await analyze([{ header: 'chore: bump deps' }])).toBeNull();
  });

  it('build-agent: feat!: … -> major', async () => {
    expect(await analyze([{ header: 'build-agent: feat!: drop legacy layer' }])).toBe('major');
  });

  it('a BREAKING CHANGE footer under an agent-prefixed header -> major', async () => {
    expect(
      await analyze([
        {
          header: 'build-agent: feat: add forgeProviders assembly',
          body: 'BREAKING CHANGE: assembly signature changed',
        },
      ]),
    ).toBe('major');
  });

  it('a mixed set of all release types -> major (highest wins)', async () => {
    expect(
      await analyze([
        { header: 'build-agent: feat: add forgeProviders assembly' },
        { header: 'review-patch-agent: fix: correct token resolution' },
        { header: 'plan-orchestrator: chore: expand README' },
        { header: 'document-agent: docs: document package build' },
        { header: 'build-agent: feat!: drop legacy layer' },
      ]),
    ).toBe('major');
  });

  it('an ADW-only housekeeping batch (chore + docs) -> null, i.e. no publish', async () => {
    expect(
      await analyze([
        { header: 'plan-orchestrator: chore: expand README' },
        { header: 'document-agent: docs: document package build' },
      ]),
    ).toBeNull();
  });
});

/**
 * Configuration-contract test for `release.config.js`, mirroring
 * `packageExports.test.ts`'s style: asserts the shape of the manifest
 * itself rather than any build output. Confirms the dry-run mode switch
 * (`SEMANTIC_RELEASE_DRY_RUN=true`) drops both plugins that require a
 * credential, so the PR dry-run job can never accidentally publish. The
 * notes-generator block exists because the `conventionalcommits` preset
 * major must match the writer major bundled by the stable
 * `@semantic-release/release-notes-generator` (preset 10.x needs writer 9;
 * the stable plugin ships writer 8), and only rendering real notes catches
 * that drift.
 */
import { afterEach, describe, expect, it } from 'vitest';
import { generateNotes } from '@semantic-release/release-notes-generator';
import releaseConfig from '../../release.config.js';

interface PluginEntry {
  0: string;
  1?: unknown;
}

function pluginNames(plugins: unknown[]): string[] {
  return (plugins as PluginEntry[]).map((entry) => entry[0]);
}

describe('release.config.js — configuration contract', () => {
  it('branches is exactly ["main"]', () => {
    expect(releaseConfig.branches).toEqual(['main']);
  });

  it('tagFormat is "v${version}"', () => {
    expect(releaseConfig.tagFormat).toBe('v${version}');
  });

  it('normal mode plugin list is commit-analyzer, notes-generator, npm, github in order', () => {
    expect(pluginNames(releaseConfig.plugins)).toEqual([
      '@semantic-release/commit-analyzer',
      '@semantic-release/release-notes-generator',
      '@semantic-release/npm',
      '@semantic-release/github',
    ]);
  });

  it('the analyzer and the notes generator receive the same parserOpts object identity', () => {
    const [, analyzerConfig] = releaseConfig.plugins[0] as [string, { parserOpts: unknown }];
    const [, notesConfig] = releaseConfig.plugins[1] as [string, { parserOpts: unknown }];
    expect(analyzerConfig.parserOpts).toBe(notesConfig.parserOpts);
  });

  it('parserOpts.headerCorrespondence is exactly ["type", "scope", "subject"]', () => {
    const [, analyzerConfig] = releaseConfig.plugins[0] as [string, { parserOpts: { headerCorrespondence: string[] } }];
    expect(analyzerConfig.parserOpts.headerCorrespondence).toEqual(['type', 'scope', 'subject']);
  });
});

describe('release.config.js — dry-run mode', () => {
  const originalEnv = process.env.SEMANTIC_RELEASE_DRY_RUN;

  afterEach(() => {
    if (originalEnv === undefined) {
      delete process.env.SEMANTIC_RELEASE_DRY_RUN;
    } else {
      process.env.SEMANTIC_RELEASE_DRY_RUN = originalEnv;
    }
  });

  it('drops the npm and github plugins, keeping only analyzer and notes-generator', async () => {
    process.env.SEMANTIC_RELEASE_DRY_RUN = 'true';
    const dryRunModulePath: string = '../../release.config.js?dryrun';
    const dryRunConfig = (await import(dryRunModulePath)).default;

    expect(pluginNames(dryRunConfig.plugins)).toEqual([
      '@semantic-release/commit-analyzer',
      '@semantic-release/release-notes-generator',
    ]);
  });
});

describe('release.config.js — release notes render under the shipped preset', () => {
  const [, notesConfig] = releaseConfig.plugins[1] as [string, { preset: string; parserOpts: Record<string, unknown> }];
  const noopLogger = { log() {}, error() {} };

  async function render(headers: string[]): Promise<string> {
    return generateNotes(notesConfig, {
      commits: headers.map((message, index) => ({ hash: String(index).repeat(40), message })),
      logger: noopLogger,
      cwd: process.cwd(),
      env: {},
      options: { repositoryUrl: 'https://github.com/paysdoc/devplatform.git' },
      lastRelease: { version: '1.0.0', gitTag: 'v1.0.0', gitHead: '0'.repeat(40) },
      nextRelease: { version: '1.1.0', gitTag: 'v1.1.0', gitHead: '1'.repeat(40), type: 'minor' },
    });
  }

  it('generateNotes renders agent-prefixed feat/fix commits under Features and Bug Fixes', async () => {
    const notes = await render([
      'build-agent: feat: add forgeProviders assembly',
      'review-patch-agent: fix: correct token resolution',
      'feat: add worktree probe',
    ]);

    expect(notes).toContain('### Features');
    expect(notes).toContain('* add forgeProviders assembly');
    expect(notes).toContain('* add worktree probe');
    expect(notes).toContain('### Bug Fixes');
    expect(notes).toContain('* correct token resolution');
  });

  it('strips the agent prefix from rendered subjects and omits non-releasing chore commits', async () => {
    const notes = await render([
      'build-agent: feat: add forgeProviders assembly',
      'plan-orchestrator: chore: expand README',
    ]);

    expect(notes).not.toContain('build-agent:');
    expect(notes).not.toContain('plan-orchestrator:');
    expect(notes).not.toContain('expand README');
  });
});

